#!/bin/sh
set -eu
root=$(CDPATH= cd -- "$(dirname "$0")/.." && pwd)
# Regenerate the self-contained MicroPython embed source set under
# build/micropython_embed (py/ + genhdr/ + shared/runtime/ + port/).
# Pinned source comes from scripts/fetch-deps.sh. Requires make + python3.
#
# The qstr/module tables are pre-generated by scanning the sources with the
# port config in effect, so generation MUST use the same config as the build:
# src/py/mpconfigport.h is copied into a scratch dir and make runs from there
# (embed.mk puts that dir first via -I.). Pass --force to regenerate.
mp="$root/third_party/micropython"
out="$root/build/micropython_embed"
work="$root/build/py-embed-work"

if [ ! -f "$mp/ports/embed/embed.mk" ]; then
    echo "third_party/micropython missing; run ./scripts/fetch-deps.sh first" >&2
    exit 1
fi

if [ "${1:-}" = "--force" ]; then
    rm -rf "$out" "$work"
fi

if [ -f "$out/genhdr/qstrdefs.generated.h" ] && [ -f "$out/port/micropython_embed.h" ] \
    && [ "$out/genhdr/qstrdeps.stamp" -nt "$root/src/py/mpconfigport.h" ]; then
    exit 0
fi

mkdir -p "$work" "$root/build"
cp "$root/src/py/mpconfigport.h" "$work/mpconfigport.h"
cat > "$work/Makefile" <<EOF
MICROPYTHON_TOP = $mp
include \$(MICROPYTHON_TOP)/ports/embed/embed.mk
EOF

cd "$work"
make PACKAGE_DIR="$out" >/dev/null

[ -f "$out/genhdr/qstrdefs.generated.h" ] || { echo "embed generation failed" >&2; exit 1; }
touch "$out/genhdr/qstrdeps.stamp"
echo "micropython embed sources ready: $out"
